<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Falling Sand Sandbox</title>
<style>
  :root{
    --bg:#0e0f13;
    --panel:#1a1c22;
    --border:#2c2f38;
    --text:#e8e8ec;
    --accent:#4fa3ff;
  }
  html,body{
    margin:0; padding:0; height:100%;
    background:var(--bg);
    color:var(--text);
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
    display:flex;
    flex-direction:column;
    align-items:center;
    justify-content:center;
    min-height:100vh;
    gap:16px;
  }
  h1{
    font-size:18px;
    font-weight:600;
    letter-spacing:0.5px;
    color:#aab2c5;
    margin:0;
  }
  #stage{
    display:flex;
    flex-direction:column;
    align-items:center;
    gap:12px;
  }
  #sand{
    background:#000;
    border:2px solid var(--border);
    border-radius:6px;
    image-rendering:pixelated;
    cursor:crosshair;
    box-shadow:0 0 30px rgba(79,163,255,0.08);
  }
  #controls{
    display:flex;
    flex-wrap:wrap;
    gap:8px;
    justify-content:center;
    max-width:520px;
    background:var(--panel);
    padding:10px;
    border-radius:10px;
    border:1px solid var(--border);
  }
  button{
    background:#22252d;
    color:var(--text);
    border:1px solid var(--border);
    padding:8px 14px;
    border-radius:8px;
    font-size:13px;
    cursor:pointer;
    transition:background 0.15s, transform 0.05s, border-color 0.15s;
    display:flex;
    align-items:center;
    gap:6px;
  }
  button:hover{
    background:#2a2e38;
  }
  button:active{
    transform:scale(0.96);
  }
  button.active{
    border-color:var(--accent);
    background:#233247;
    box-shadow:0 0 0 1px var(--accent) inset;
  }
  .swatch{
    width:10px;
    height:10px;
    border-radius:3px;
    display:inline-block;
  }
  #clear{
    background:#3a1f22;
    border-color:#5a2a2e;
  }
  #clear:hover{
    background:#4a262a;
  }
  .hint{
    color:#777f8f;
    font-size:12px;
    max-width:500px;
    text-align:center;
  }
</style>
</head>
<body>

<h1>Falling Sand Sandbox</h1>

<div id="stage">
  <canvas id="sand" width="500" height="500"></canvas>

  <div id="controls">
    <button id="mat-sand" class="mat active"><span class="swatch" style="background:#e0c068"></span>Sand</button>
    <button id="mat-water" class="mat"><span class="swatch" style="background:#3d8ee8"></span>Water</button>
    <button id="mat-wall" class="mat"><span class="swatch" style="background:#8a8f9a"></span>Wall</button>
    <button id="mat-acid" class="mat"><span class="swatch" style="background:#7bdb3a"></span>Acid</button>
    <button id="mat-empty" class="mat"><span class="swatch" style="background:#111318;border:1px solid #444"></span>Eraser</button>
    <button id="clear">Clear All</button>
  </div>
  <div class="hint">Drag on the canvas to paint. Pick a material above, then click &amp; drag. Sand falls and piles, water flows and spreads, acid eats sand &amp; walls.</div>
</div>

<script>
(function(){
  "use strict";

  // ---------- Grid setup ----------
  const W = 100, H = 100;
  const CELL = 5; // px per cell -> 500x500 canvas (>=400x400 required)

  const EMPTY=0, SAND=1, WATER=2, WALL=3, ACID=4;
  const NAME_BY_ID = ["empty","sand","water","wall","acid"];
  const ID_BY_NAME = {empty:EMPTY, sand:SAND, water:WATER, wall:WALL, acid:ACID};

  const COLORS = {
    [EMPTY]: "#0d0e12",
    [SAND]:  "#e0c068",
    [WATER]: "#3d8ee8",
    [WALL]:  "#8a8f9a",
    [ACID]:  "#7bdb3a"
  };

  let grid = new Uint8Array(W*H);

  function index(x,y){ return y*W + x; }
  function inBounds(x,y){ return x>=0 && x<W && y>=0 && y<H; }

  // ---------- Simulation step ----------
  function swapCells(a,b,processed){
    const tmp = grid[a];
    grid[a] = grid[b];
    grid[b] = tmp;
    processed[a]=1;
    processed[b]=1;
  }

  function moveSand(x,y,processed){
    const idx = index(x,y);
    const by = y+1;
    if(by>=H) return; // resting on bottom boundary
    const bidx = index(x,by);
    const bt = grid[bidx];
    if(!processed[bidx] && (bt===EMPTY || bt===WATER || bt===ACID)){
      swapCells(idx,bidx,processed);
      return;
    }
    const order = Math.random()<0.5 ? [-1,1] : [1,-1];
    for(const dx of order){
      const nx = x+dx;
      if(nx<0 || nx>=W) continue;
      const nidx = index(nx,by);
      const nt = grid[nidx];
      if(!processed[nidx] && (nt===EMPTY || nt===WATER || nt===ACID)){
        swapCells(idx,nidx,processed);
        return;
      }
    }
    // rests
  }

  function moveLiquid(x,y,processed){
    const idx = index(x,y);
    const by = y+1;
    if(by<H){
      const bidx = index(x,by);
      if(grid[bidx]===EMPTY && !processed[bidx]){
        swapCells(idx,bidx,processed);
        return;
      }
      const order = Math.random()<0.5 ? [-1,1] : [1,-1];
      for(const dx of order){
        const nx = x+dx;
        if(nx<0 || nx>=W) continue;
        const nidx = index(nx,by);
        if(grid[nidx]===EMPTY && !processed[nidx]){
          swapCells(idx,nidx,processed);
          return;
        }
      }
    }
    // spread sideways on same row
    const order2 = Math.random()<0.5 ? [-1,1] : [1,-1];
    for(const dx of order2){
      const nx = x+dx;
      if(nx<0 || nx>=W) continue;
      const nidx = index(nx,y);
      if(grid[nidx]===EMPTY && !processed[nidx]){
        swapCells(idx,nidx,processed);
        return;
      }
    }
  }

  function moveAcid(x,y,processed){
    const idx = index(x,y);
    const neighbors = [[0,1],[-1,0],[1,0]];
    if(Math.random()<0.5) neighbors.reverse();

    let dissolved = false;
    for(const [dx,dy] of neighbors){
      const nx = x+dx, ny = y+dy;
      if(!inBounds(nx,ny)) continue;
      const nidx = index(nx,ny);
      const t = grid[nidx];
      if((t===SAND || t===WALL) && !processed[nidx]){
        grid[nidx] = EMPTY;
        processed[nidx] = 1;
        dissolved = true;
        break;
      }
    }
    if(dissolved && Math.random()<0.35){
      grid[idx] = EMPTY;
      processed[idx] = 1;
      return;
    }
    moveLiquid(x,y,processed);
  }

  function step(){
    const processed = new Uint8Array(W*H);
    for(let y=H-1; y>=0; y--){
      const leftToRight = Math.random()<0.5;
      for(let xi=0; xi<W; xi++){
        const x = leftToRight ? xi : (W-1-xi);
        const idx = index(x,y);
        if(processed[idx]) continue;
        const t = grid[idx];
        if(t===EMPTY || t===WALL) continue;
        if(t===SAND) moveSand(x,y,processed);
        else if(t===WATER) moveLiquid(x,y,processed);
        else if(t===ACID) moveAcid(x,y,processed);
      }
    }
  }

  // ---------- Rendering ----------
  const canvas = document.getElementById("sand");
  canvas.width = W*CELL;
  canvas.height = H*CELL;
  canvas.style.width = (W*CELL)+"px";
  canvas.style.height = (H*CELL)+"px";
  const ctx = canvas.getContext("2d");

  function render(){
    for(let y=0;y<H;y++){
      for(let x=0;x<W;x++){
        const t = grid[index(x,y)];
        ctx.fillStyle = COLORS[t];
        ctx.fillRect(x*CELL, y*CELL, CELL, CELL);
      }
    }
  }

  // ---------- Public API ----------
  window.sim = {
    w: W,
    h: H,
    tick(n){
      n = n|0;
      for(let i=0;i<n;i++) step();
      render();
    },
    get(x,y){
      if(!inBounds(x,y)) return "empty";
      return NAME_BY_ID[grid[index(x,y)]];
    },
    set(x,y,material){
      if(!inBounds(x,y)) return;
      const id = ID_BY_NAME[material];
      if(id===undefined) return;
      grid[index(x,y)] = id;
    },
    clear(){
      grid.fill(EMPTY);
      render();
    }
  };

  // ---------- UI: material selection ----------
  let currentMaterial = "sand";
  const matButtons = {
    sand: document.getElementById("mat-sand"),
    water: document.getElementById("mat-water"),
    wall: document.getElementById("mat-wall"),
    acid: document.getElementById("mat-acid"),
    empty: document.getElementById("mat-empty"),
  };
  function selectMaterial(name){
    currentMaterial = name;
    Object.entries(matButtons).forEach(([k,btn])=>{
      btn.classList.toggle("active", k===name);
    });
  }
  matButtons.sand.addEventListener("click", ()=>selectMaterial("sand"));
  matButtons.water.addEventListener("click", ()=>selectMaterial("water"));
  matButtons.wall.addEventListener("click", ()=>selectMaterial("wall"));
  matButtons.acid.addEventListener("click", ()=>selectMaterial("acid"));
  matButtons.empty.addEventListener("click", ()=>selectMaterial("empty"));

  document.getElementById("clear").addEventListener("click", ()=>{
    window.sim.clear();
  });

  // ---------- UI: painting ----------
  let painting = false;
  const BRUSH_RADIUS = 2;

  function cellFromEvent(e){
    const rect = canvas.getBoundingClientRect();
    const cx = (e.clientX - rect.left) / rect.width * W;
    const cy = (e.clientY - rect.top) / rect.height * H;
    return [Math.floor(cx), Math.floor(cy)];
  }

  function paintAt(cx,cy){
    const id = ID_BY_NAME[currentMaterial];
    for(let dy=-BRUSH_RADIUS; dy<=BRUSH_RADIUS; dy++){
      for(let dx=-BRUSH_RADIUS; dx<=BRUSH_RADIUS; dx++){
        if(dx*dx+dy*dy > BRUSH_RADIUS*BRUSH_RADIUS+1) continue;
        const x = cx+dx, y = cy+dy;
        if(inBounds(x,y)){
          grid[index(x,y)] = id;
        }
      }
    }
  }

  canvas.addEventListener("pointerdown", (e)=>{
    painting = true;
    const [x,y] = cellFromEvent(e);
    paintAt(x,y);
    e.preventDefault();
  });
  canvas.addEventListener("pointermove", (e)=>{
    if(!painting) return;
    const [x,y] = cellFromEvent(e);
    paintAt(x,y);
  });
  window.addEventListener("pointerup", ()=>{ painting=false; });
  canvas.addEventListener("pointerleave", ()=>{ /* keep painting if button still down */ });

  // ---------- Animation loop ----------
  function loop(){
    step();
    render();
    requestAnimationFrame(loop);
  }
  render();
  requestAnimationFrame(loop);

})();
</script>
</body>
</html>
